window.BANK = window.BANK || {};
window.BANK.pppk = window.BANK.pppk || [];
window.BANK.pppk.push(
{ q:"Anda mengetahui rekan satu tim sengaja memasukkan angka fiktif pada laporan pertanggungjawaban kegiatan untuk menutupi selisih kas yang hilang. Nominalnya kecil dan rekan itu meyakinkan Anda bahwa tidak akan ada yang tahu. Apa yang Anda lakukan?", opts:["Mengingatkan rekan tersebut secara pribadi agar memperbaiki laporan sesuai fakta dan melaporkannya ke atasan atau unit pengawas internal jika tidak diperbaiki","Ikut diam karena nominalnya kecil dan tidak ingin merusak hubungan baik dengan rekan kerja","Melaporkan langsung ke atasan tanpa berbicara dulu dengan rekan tersebut agar cepat selesai","Meminta bagian dari selisih tersebut sebagai kompensasi karena telah menutupi rahasia itu","Membiarkan saja dan berpura-pura tidak tahu selama tidak ditanya oleh siapa pun"], a:0, sub:"Manajerial", pembahasan:"Respons terbaik adalah menegur secara langsung agar rekan memperbaiki kesalahannya sekaligus tetap membuka jalur eskalasi ke pengawas internal bila tidak ada perbaikan, sehingga integritas tegak namun tetap manusiawi. Melapor langsung tanpa konfirmasi (opsi C) kurang ideal karena melewati kesempatan klarifikasi, sedangkan diam (B, E) dan ikut menikmati hasil pelanggaran (D) jelas mencederai integritas dan merupakan pilihan terburuk." },
{ q:"Atasan meminta Anda menyusun laporan capaian program untuk pimpinan yang lebih tinggi dengan menonjolkan angka-angka yang sebenarnya belum sepenuhnya tercapai, dengan alasan agar citra unit kerja tetap baik. Sikap Anda?", opts:["Menyusun laporan sesuai data riil dan menyampaikan kepada atasan bahwa capaian yang belum tercapai perlu disertai rencana tindak lanjut, bukan dipoles","Menuruti permintaan atasan karena itu perintah langsung dan menolak berisiko terhadap karier","Menyusun dua versi laporan, satu jujur untuk arsip pribadi dan satu sesuai permintaan atasan","Melaporkan langsung ke inspektorat tanpa mendiskusikan dulu dengan atasan","Menunda penyerahan laporan tanpa memberi penjelasan apa pun kepada atasan"], a:0, sub:"Manajerial", pembahasan:"Pilihan A menjaga integritas data sekaligus tetap solutif dan sopan terhadap atasan dengan menawarkan alternatif yang konstruktif. Melapor ke inspektorat langsung (D) melewati mekanisme internal yang wajar dan bisa merusak relasi kerja tanpa upaya penyelesaian lebih dulu, sedangkan menuruti (B), membuat laporan ganda (C), atau menunda tanpa penjelasan (E) tidak menyelesaikan masalah integritas secara tegas." },
{ q:"Seorang vendor yang baru saja memenangkan lelang pengadaan secara sah di instansi Anda mengirimkan hadiah pribadi cukup mahal ke rumah Anda sebagai 'ucapan terima kasih'. Tindakan yang paling tepat adalah?", opts:["Menolak dan mengembalikan hadiah tersebut, serta melaporkan kejadian ini kepada atasan atau unit pengendalian gratifikasi sesuai ketentuan","Menerima hadiah karena proses lelang sudah selesai secara sah sehingga tidak melanggar aturan","Menerima hadiah tetapi menyimpannya sebagai milik pribadi tanpa melaporkan ke siapa pun","Mengembalikan hadiah secara diam-diam tanpa melaporkan kepada pihak mana pun","Meminta vendor mengganti hadiah dengan bentuk lain yang tidak mencolok agar tidak menimbulkan kecurigaan"], a:0, sub:"Manajerial", pembahasan:"Menolak sekaligus melaporkan ke unit pengendalian gratifikasi adalah langkah paling transparan dan sesuai aturan ASN, karena hadiah terkait jabatan tetap berpotensi gratifikasi meski proses lelang telah sah. Mengembalikan secara diam-diam (D) lebih baik daripada menerima namun masih kurang transparan, sedangkan menerima (B, C) atau meminta bentuk lain (E) jelas melanggar prinsip integritas." },
{ q:"Anda tergabung dalam tim lintas bidang untuk menyelesaikan proyek dengan tenggat ketat. Salah satu anggota tim jarang hadir rapat dan tidak menyelesaikan bagian tugasnya, sehingga beban kerja anggota lain bertambah. Langkah Anda sebagai anggota tim adalah?", opts:["Mengajak bicara empat mata untuk memahami kendalanya, lalu bersama tim mencari solusi pembagian tugas ulang jika diperlukan","Mengambil alih seluruh tugasnya tanpa berbicara dengannya agar proyek tidak terlambat","Melaporkan langsung ke atasan agar anggota tersebut diberi sanksi tegas","Membiarkan saja karena itu bukan tanggung jawab Anda untuk menegurnya","Menyindirnya di grup chat tim agar dia merasa malu dan segera bekerja"], a:0, sub:"Manajerial", pembahasan:"Komunikasi personal untuk memahami akar masalah sebelum mencari solusi bersama tim adalah pendekatan kerja sama yang paling konstruktif dan menjaga hubungan kerja. Mengambil alih tugas (B) menyelesaikan gejala bukan akar masalah dan membebani diri sendiri, melapor langsung tanpa klarifikasi (C) terlalu cepat eskalasi, sedangkan membiarkan (D) dan menyindir di depan umum (E) tidak produktif dan berpotensi merusak kekompakan tim." },
{ q:"Anda dan seorang rekan memiliki pendapat berbeda mengenai metode kerja terbaik untuk menyelesaikan tugas bersama, namun keduanya harus tetap berkolaborasi menyelesaikan pekerjaan tersebut. Sikap paling tepat adalah?", opts:["Mengajak rekan berdiskusi untuk memahami alasan masing-masing metode, lalu menyepakati pendekatan terbaik atau kombinasi keduanya demi hasil optimal","Bersikeras menggunakan metode Anda karena yakin lebih benar tanpa mendengarkan alasan rekan","Mengalah sepenuhnya mengikuti metode rekan agar tidak terjadi konflik, meski kurang yakin efektif","Mengerjakan bagian Anda dengan metode sendiri dan membiarkan rekan mengerjakan dengan caranya tanpa koordinasi","Meminta atasan menentukan metode mana yang harus dipakai tanpa mencoba berdiskusi terlebih dahulu"], a:0, sub:"Manajerial", pembahasan:"Diskusi terbuka untuk memahami dasar argumen masing-masing lalu mencari solusi terbaik bersama mencerminkan kerja sama dan komunikasi yang matang. Mengalah tanpa evaluasi (C) atau bersikeras sepihak (B) kurang ideal, bekerja tanpa koordinasi (D) berisiko hasil yang tidak konsisten, dan langsung melempar ke atasan (E) menunjukkan kurangnya inisiatif menyelesaikan masalah sendiri." },
{ q:"Tim lain di kantor Anda sedang kewalahan menghadapi tenggat mendesak, sementara pekerjaan Anda sendiri juga menumpuk dan harus selesai minggu ini. Mereka meminta bantuan Anda. Apa yang sebaiknya Anda lakukan?", opts:["Mengevaluasi prioritas pekerjaan Anda, lalu menawarkan bantuan sebatas waktu yang tersedia atau membantu mencarikan solusi lain seperti berkoordinasi dengan atasan terkait pembagian sumber daya","Menolak mentah-mentah karena pekerjaan sendiri adalah prioritas utama","Langsung mengiyakan membantu penuh meskipun berisiko pekerjaan sendiri terbengkalai","Membantu diam-diam tanpa memberi tahu atasan masing-masing tim","Menyuruh tim tersebut menyelesaikan sendiri karena bukan tanggung jawab Anda"], a:0, sub:"Manajerial", pembahasan:"Sikap paling ideal adalah tetap kolaboratif namun realistis, mengukur kapasitas diri dan melibatkan atasan agar pembagian sumber daya lebih terkoordinasi. Menolak total (B, E) mengabaikan semangat kerja sama, sedangkan membantu penuh tanpa mempertimbangkan pekerjaan sendiri (C) atau membantu tanpa koordinasi resmi (D) berisiko menimbulkan masalah baru." },
{ q:"Anda ditugaskan menyampaikan kebijakan baru dari pimpinan mengenai pemotongan tunjangan tertentu kepada seluruh pegawai, sebuah kebijakan yang diperkirakan akan tidak populer. Bagaimana cara terbaik menyampaikannya?", opts:["Menyampaikan secara terbuka dan jujur disertai alasan serta dasar kebijakan, memberi ruang tanya jawab agar pegawai memahami konteksnya","Menyampaikan seadanya tanpa penjelasan agar cepat selesai dan menghindari pertanyaan sulit","Menunda penyampaian selama mungkin dengan harapan pegawai mengetahuinya dari sumber lain","Menyampaikan hanya kepada perwakilan pegawai dan meminta mereka menyebarkan sendiri ke rekan-rekannya","Menyampaikan kebijakan tersebut namun menyalahkan pimpinan di depan pegawai agar Anda tidak dianggap bagian dari keputusan itu"], a:0, sub:"Manajerial", pembahasan:"Komunikasi yang transparan, disertai alasan dan ruang dialog, adalah cara terbaik menyampaikan berita tidak populer agar pesan diterima dengan pemahaman utuh. Menunda (C) atau mendelegasikan ke pihak lain (D) menghindari tanggung jawab komunikasi, menyampaikan tanpa penjelasan (B) berisiko menimbulkan kesalahpahaman, dan menyalahkan pimpinan (E) tidak profesional dan merusak soliditas organisasi." },
{ q:"Atasan Anda memberikan instruksi pekerjaan secara singkat dan kurang jelas mengenai target serta batasan waktunya, lalu segera pergi rapat di luar kota. Apa langkah paling tepat?", opts:["Menghubungi atasan untuk meminta klarifikasi singkat sebelum rapat dimulai, atau jika tidak sempat, menuliskan pemahaman Anda dan meminta konfirmasi melalui pesan agar tidak salah arah","Langsung mengerjakan sesuai tebakan terbaik Anda tanpa konfirmasi apa pun","Menunggu atasan kembali dari luar kota sebelum mulai mengerjakan apa pun","Bertanya kepada rekan kerja lain yang juga tidak mengetahui detail instruksi tersebut","Mengerjakan tugas yang menurut Anda paling mudah saja dan mengabaikan bagian yang tidak jelas"], a:0, sub:"Manajerial", pembahasan:"Mengklarifikasi secepatnya baik langsung maupun via pesan tertulis menunjukkan komunikasi proaktif dan menghindari kesalahpahaman tanpa menghambat progres kerja. Menunggu atasan kembali (C) membuang waktu berharga, mengerjakan berdasarkan tebakan (B) atau memilih bagian termudah (E) berisiko hasil tidak sesuai harapan, dan bertanya ke rekan yang sama-sama tidak tahu (D) tidak menyelesaikan akar masalah." },
{ q:"Saat melayani di loket, seorang warga mengomel keras dan menyalahkan Anda secara pribadi atas keterlambatan proses yang sebenarnya disebabkan sistem pusat yang sedang gangguan, disaksikan warga lain yang mengantre. Sikap terbaik Anda?", opts:["Tetap tenang, mendengarkan keluhannya, menjelaskan penyebab sebenarnya dengan sopan, dan menginformasikan langkah yang akan diambil untuk membantu","Membalas dengan nada tinggi agar warga tersebut berhenti berbicara kasar","Diam saja tanpa menjawab apa pun sampai warga tersebut selesai marah dan pergi","Meminta warga lain yang mengantre untuk menenangkan orang tersebut","Langsung menyuruh warga tersebut pergi karena mengganggu ketertiban antrean"], a:0, sub:"Manajerial", pembahasan:"Menjaga ketenangan, memberi penjelasan jujur, dan menawarkan solusi adalah komunikasi yang paling profesional dalam pelayanan publik meskipun sedang dikritik di depan umum. Membalas dengan emosi (B) atau mengusir (E) memperburuk situasi, diam total (C) terkesan tidak peduli, dan melibatkan warga lain (D) bukan tanggung jawab yang tepat untuk dilimpahkan." },
{ q:"Target penyelesaian program kerja Anda tidak tercapai pada akhir triwulan karena keterlambatan pencairan anggaran dari pusat, sebuah faktor di luar kendali Anda, sementara tenggat pelaporan sudah sangat dekat. Apa yang Anda lakukan?", opts:["Segera menyusun rencana percepatan yang realistis, melaporkan kendala secara transparan kepada atasan, dan mengupayakan hasil maksimal dengan sumber daya yang tersedia","Melaporkan bahwa target tercapai sepenuhnya agar terlihat baik di catatan kinerja","Menyalahkan sepenuhnya pihak pusat dalam laporan tanpa menawarkan solusi apa pun dari sisi Anda","Menunda laporan tanpa pemberitahuan sampai anggaran benar-benar cair","Berhenti berusaha mengejar target karena merasa kendalanya di luar kendali sehingga tidak akan dinilai buruk"], a:0, sub:"Manajerial", pembahasan:"Orientasi pada hasil yang matang tetap berusaha memaksimalkan capaian sekaligus transparan mengenai kendala, bukan menyerah atau memanipulasi data. Melaporkan capaian palsu (B) melanggar integritas, menyalahkan pihak lain tanpa solusi (C) tidak solutif, menunda tanpa kabar (D) tidak profesional, dan menyerah begitu saja (E) menunjukkan rendahnya orientasi hasil." },
{ q:"Anda mendapati dua pekerjaan sama-sama mendesak dengan tenggat hari ini: menyelesaikan laporan yang diminta atasan langsung dan menangani permintaan data dari unit lain yang juga penting bagi rapat pimpinan. Bagaimana Anda menyikapinya?", opts:["Segera mengomunikasikan situasi kepada kedua pihak, menawarkan solusi seperti prioritas berdasarkan urgensi rapat pimpinan, dan meminta bantuan jika diperlukan","Mengerjakan yang menurut Anda paling mudah lebih dulu tanpa mengomunikasikan apa pun kepada kedua pihak","Mengabaikan salah satu permintaan begitu saja tanpa penjelasan","Menyelesaikan keduanya secara terburu-buru dengan kualitas seadanya agar sama-sama selesai tepat waktu","Meminta perpanjangan waktu untuk kedua tugas tanpa penjelasan yang jelas kepada kedua pihak"], a:0, sub:"Manajerial", pembahasan:"Mengomunikasikan situasi secara proaktif dan menentukan prioritas berdasarkan urgensi sekaligus mencari bantuan bila perlu adalah cara terbaik mengelola dua tenggat mendesak sekaligus. Mengabaikan (C) atau meminta perpanjangan tanpa alasan jelas (E) tidak profesional, mengerjakan tanpa komunikasi (B) berisiko salah prioritas, dan mengorbankan kualitas demi kecepatan (D) merugikan hasil akhir." },
{ q:"Pekerjaan rutin Anda sebenarnya bisa diselesaikan sesuai standar minimal yang sudah cukup untuk memenuhi kewajiban, namun Anda melihat peluang untuk membuatnya lebih efisien dan bermanfaat lebih luas meski membutuhkan usaha tambahan. Sikap terbaik adalah?", opts:["Mengambil inisiatif melakukan perbaikan tersebut selama tidak mengganggu tanggung jawab utama, sambil mengomunikasikan idenya kepada atasan untuk mendapat dukungan","Cukup mengerjakan sesuai standar minimal saja karena sudah memenuhi kewajiban dan menghindari beban kerja tambahan","Melakukan perbaikan tanpa memberi tahu siapa pun meskipun berdampak pada proses kerja tim lain","Menunggu diperintah atasan terlebih dahulu sebelum melakukan perbaikan apa pun","Mengusulkan perbaikan tersebut tetapi meminta rekan lain yang mengerjakannya"], a:0, sub:"Manajerial", pembahasan:"Inisiatif untuk berorientasi pada hasil yang lebih baik sambil tetap berkomunikasi dengan atasan adalah sikap proaktif yang paling dinilai tinggi. Sekadar memenuhi standar minimal (B) atau menunggu perintah (D) menunjukkan minimnya inisiatif, melakukan perubahan sepihak tanpa koordinasi (C) berisiko mengganggu proses tim, dan melempar ke rekan lain (E) bukan bentuk inisiatif pribadi." },
{ q:"Seorang warga lanjut usia datang ke kantor Anda lima menit setelah jam pelayanan tutup, membawa berkas mendesak karena keluarganya sakit dan membutuhkan dokumen tersebut segera. Rekan kerja lain sudah bersiap pulang. Apa yang Anda lakukan?", opts:["Tetap melayani warga tersebut dengan sigap selama memungkinkan, atau jika benar-benar tidak bisa, membantu mengarahkan solusi tercepat seperti pelayanan darurat yang tersedia","Menolak dengan tegas karena jam pelayanan sudah tutup tanpa memberikan solusi lain","Menyuruh warga tersebut kembali besok tanpa penjelasan lebih lanjut","Melayani tetapi dengan sikap ketus agar warga tersebut tidak datang terlambat lagi","Mengarahkan warga tersebut ke rekan kerja lain tanpa penjelasan mengenai kondisinya"], a:0, sub:"Manajerial", pembahasan:"Pelayanan publik yang baik mengutamakan fleksibilitas dan empati terhadap kondisi mendesak masyarakat tanpa mengabaikan aturan sepenuhnya, dengan mencari solusi terbaik yang memungkinkan. Menolak tanpa solusi (B) atau menyuruh kembali tanpa penjelasan (C) mengabaikan asas pelayanan prima, melayani dengan ketus (D) tidak sopan, dan melimpahkan tanpa konteks (E) berisiko masalah tidak tertangani." },
{ q:"Anda menyadari prosedur pengurusan izin di unit kerja Anda sangat berbelit dan sering menyulitkan masyarakat, padahal wewenang Anda sebagai pelaksana terbatas untuk mengubah prosedur tersebut secara langsung. Langkah paling tepat adalah?", opts:["Mendokumentasikan permasalahan yang dihadapi masyarakat dan mengusulkan penyederhanaan prosedur kepada atasan atau melalui forum perbaikan layanan yang ada","Mengabaikan masalah tersebut karena bukan wewenang Anda untuk mengubah prosedur","Membantu masyarakat dengan cara menyalahi prosedur resmi demi mempercepat proses","Mengeluh kepada masyarakat bahwa prosedur memang buruk tanpa berusaha mengusulkan perbaikan","Membiarkan masyarakat mencari tahu sendiri cara mempercepat proses tanpa bimbingan resmi"], a:0, sub:"Manajerial", pembahasan:"Mengusulkan perbaikan secara formal melalui atasan atau forum resmi adalah cara paling konstruktif menindaklanjuti masalah di luar wewenang langsung. Menyalahi prosedur (C) berisiko pelanggaran, mengabaikan (B) dan membiarkan tanpa bimbingan (E) tidak mencerminkan pelayanan publik yang baik, sedangkan mengeluh tanpa solusi (D) hanya menurunkan kepercayaan masyarakat." },
{ q:"Anda menemukan bahwa data yang telah diberikan kepada seorang warga dalam layanan administrasi ternyata keliru akibat kesalahan input dan berpotensi merugikan warga tersebut di kemudian hari. Apa yang Anda lakukan?", opts:["Segera menghubungi warga tersebut, menjelaskan kekeliruan secara jujur, dan membantu proses perbaikan data secepatnya","Membiarkan saja karena berharap warga tersebut tidak menyadari kesalahan tersebut","Menunggu warga tersebut yang datang mengeluh terlebih dahulu sebelum memperbaiki","Memperbaiki data tanpa memberi tahu warga tersebut mengenai adanya kesalahan","Melaporkan kesalahan kepada atasan tetapi menunda tindak lanjut kepada warga"], a:0, sub:"Manajerial", pembahasan:"Proaktif menginformasikan dan memperbaiki kesalahan sendiri kepada masyarakat yang terdampak adalah bentuk tanggung jawab pelayanan publik yang paling tinggi. Membiarkan (B) atau menunggu keluhan (C) berisiko merugikan warga lebih jauh, memperbaiki tanpa transparansi (D) mengurangi kepercayaan, dan menunda tindak lanjut (E) memperlambat penyelesaian masalah yang sudah diketahui." },
{ q:"Sebagai pegawai yang lebih senior, Anda memiliki staf baru yang kesulitan memahami tugas-tugas dasar dan sering meminta bantuan berulang kali untuk hal yang sama. Sikap terbaik Anda adalah?", opts:["Meluangkan waktu membimbingnya secara sabar, membuatkan panduan sederhana yang bisa dijadikan referensi mandiri ke depannya","Mengerjakan tugasnya secara langsung setiap kali dia bertanya agar cepat selesai","Menyuruhnya mencari tahu sendiri tanpa bantuan apa pun karena Anda merasa sudah cukup sibuk","Melaporkan kepada atasan bahwa staf tersebut tidak kompeten dan meminta dipindahkan","Menghindarinya setiap kali dia mendekat untuk bertanya agar tidak direpotkan"], a:0, sub:"Manajerial", pembahasan:"Membimbing dengan sabar sekaligus membekali alat bantu mandiri mencerminkan pengembangan diri dan orang lain yang berkelanjutan, bukan sekadar menyelesaikan masalah sesaat. Mengerjakan langsung (B) membuatnya makin bergantung, mengabaikan (C, E) tidak mendukung pengembangan, dan melapor untuk dipindahkan (D) terlalu cepat menyerah tanpa upaya pembinaan lebih dulu." },
{ q:"Anda ditawari mengikuti pelatihan pengembangan kompetensi yang sangat relevan dengan tugas Anda, namun jadwalnya bertabrakan dengan beberapa pekerjaan rutin yang harus diselesaikan minggu itu. Apa yang Anda lakukan?", opts:["Berkoordinasi dengan atasan dan rekan kerja untuk mengatur ulang jadwal atau pendelegasian tugas sementara agar tetap bisa mengikuti pelatihan tanpa mengorbankan pekerjaan","Menolak pelatihan tersebut sepenuhnya karena pekerjaan rutin dianggap lebih penting","Mengikuti pelatihan tanpa memberi tahu siapa pun mengenai pekerjaan yang tertunda","Meminta rekan kerja mengerjakan seluruh tugas Anda tanpa penjelasan yang jelas","Mengikuti sebagian pelatihan saja secara tidak konsisten tanpa koordinasi apa pun"], a:0, sub:"Manajerial", pembahasan:"Koordinasi yang baik memungkinkan pengembangan diri tetap berjalan tanpa mengorbankan tanggung jawab pekerjaan, mencerminkan perencanaan yang matang. Menolak pelatihan (B) mengabaikan pentingnya pengembangan diri, mengikuti tanpa koordinasi (C, D) berisiko menimbulkan masalah kerja tim, dan mengikuti setengah-setengah (E) tidak memberikan hasil optimal dari pelatihan." },
{ q:"Salah satu anggota tim Anda berulang kali melakukan kesalahan yang sama dalam pekerjaannya meskipun sudah diingatkan sebelumnya. Sebagai rekan kerja, apa langkah yang paling tepat?", opts:["Mengajak diskusi untuk memahami akar penyebab kesalahan berulang tersebut, lalu bersama-sama mencari solusi seperti pelatihan tambahan atau panduan kerja yang lebih jelas","Menegurnya dengan keras di depan tim agar dia jera dan tidak mengulangi kesalahan","Mengambil alih tugasnya secara permanen agar kesalahan tidak terjadi lagi","Membiarkan kesalahan tersebut terus terjadi karena bukan tanggung jawab Anda untuk menegurnya","Melaporkan langsung ke atasan untuk meminta sanksi tanpa mencoba mencari solusi terlebih dahulu"], a:0, sub:"Manajerial", pembahasan:"Mencari akar masalah bersama sebelum menentukan solusi pengembangan adalah pendekatan paling efektif dan suportif dalam pengembangan orang lain. Menegur keras di depan umum (B) bisa menjatuhkan mental tanpa menyelesaikan akar masalah, mengambil alih (C) tidak mendidik, membiarkan (D) tidak bertanggung jawab sebagai rekan tim, dan melapor langsung tanpa upaya (E) terlalu prematur." },
{ q:"Instansi Anda menerapkan sistem kerja digital baru yang menggantikan proses manual yang sudah lama dijalankan pegawai, dan banyak pegawai senior merasa kesulitan beradaptasi hingga menunjukkan penolakan. Sebagai bagian dari tim, sikap Anda?", opts:["Membantu menjelaskan manfaat sistem baru dengan sabar, memberikan pendampingan praktis kepada rekan yang kesulitan, dan menyampaikan masukan konstruktif jika ada kendala teknis","Mengikuti sistem baru sendiri tanpa peduli apakah rekan lain bisa beradaptasi atau tidak","Ikut menolak sistem baru bersama rekan senior agar tidak dianggap berbeda sendiri","Mengkritik sistem baru secara terbuka tanpa memberikan solusi apa pun","Menunggu instansi memaksa semua orang baru menggunakannya tanpa membantu proses transisi"], a:0, sub:"Manajerial", pembahasan:"Mendukung perubahan dengan aktif membantu adaptasi rekan kerja sekaligus tetap menyampaikan masukan konstruktif adalah sikap terbaik dalam mengelola perubahan organisasi. Bersikap acuh (B) atau menunggu paksaan (E) tidak mendukung transisi tim, ikut menolak (C) menghambat perubahan yang diperlukan, dan mengkritik tanpa solusi (D) tidak produktif." },
{ q:"Anda tiba-tiba dimutasi ke unit kerja baru dengan tugas yang sangat berbeda dari keahlian Anda selama ini, dan perubahan tersebut diinformasikan mendadak tanpa banyak persiapan. Bagaimana Anda menyikapinya?", opts:["Menerima penugasan dengan sikap terbuka, segera mempelajari tugas baru, dan meminta bimbingan kepada rekan atau atasan di unit baru agar cepat beradaptasi","Menolak mutasi tersebut dan meminta dikembalikan ke posisi lama tanpa alasan yang jelas","Menerima tugas baru namun bekerja seadanya karena merasa tidak diberi persiapan cukup","Mengeluh secara terus-menerus kepada rekan kerja mengenai ketidakadilan mutasi tersebut","Menunda mempelajari tugas baru sampai merasa benar-benar siap secara mental"], a:0, sub:"Manajerial", pembahasan:"Sikap terbuka dan proaktif mempelajari tugas baru mencerminkan kemampuan mengelola perubahan yang baik meski situasinya mendadak. Menolak (B) tidak realistis dalam konteks penugasan resmi, bekerja seadanya (C) atau menunda belajar (E) memperlambat adaptasi, dan mengeluh terus-menerus (D) tidak produktif serta bisa memengaruhi semangat tim." },
{ q:"Pimpinan baru menetapkan kebijakan kerja yang cukup bertentangan dengan kebiasaan lama tim yang sudah nyaman dijalankan selama bertahun-tahun, dan beberapa rekan mengajak Anda untuk sama-sama mengabaikan kebijakan tersebut secara diam-diam. Sikap Anda?", opts:["Menjalankan kebijakan baru sesuai arahan sambil menyampaikan masukan atau kekhawatiran secara konstruktif melalui forum resmi jika memang ada kendala penerapan","Ikut mengabaikan kebijakan tersebut bersama rekan-rekan karena merasa lebih nyaman dengan cara lama","Menjalankan kebijakan baru tetapi diam-diam menyabotase pelaksanaannya agar terlihat gagal","Melaporkan rekan-rekan yang menolak kebijakan tersebut kepada pimpinan tanpa berdiskusi lebih dulu","Ikut-ikutan mengabaikan kebijakan hanya di depan rekan, namun berpura-pura patuh di depan pimpinan"], a:0, sub:"Manajerial", pembahasan:"Menjalankan kebijakan resmi sambil tetap membuka ruang masukan yang konstruktif adalah sikap paling tepat dalam mengelola perubahan kebijakan pimpinan. Mengabaikan (B) atau menyabotase (C, E) mencerminkan ketidakpatuhan dan kurangnya integritas, sedangkan melapor tanpa mencoba dialog (D) berpotensi merusak hubungan tim tanpa upaya penyelesaian internal terlebih dahulu." },
{ q:"Anda menghadapi situasi mendesak yang membutuhkan keputusan cepat terkait pelayanan masyarakat, sementara atasan yang biasanya memberi arahan sedang tidak bisa dihubungi sama sekali. Apa yang Anda lakukan?", opts:["Mengambil keputusan terbaik berdasarkan aturan dan wewenang yang Anda miliki, lalu segera melaporkan keputusan tersebut kepada atasan begitu bisa dihubungi","Menunda pelayanan masyarakat sampai atasan berhasil dihubungi meskipun memakan waktu lama","Mengambil keputusan sendiri tanpa berniat melaporkannya kepada siapa pun setelahnya","Menyuruh masyarakat menunggu tanpa kepastian waktu tanpa upaya mencari solusi lain","Meminta rekan kerja yang levelnya sama untuk mengambil keputusan tersebut menggantikan Anda"], a:0, sub:"Manajerial", pembahasan:"Mengambil keputusan cepat sesuai wewenang lalu tetap akuntabel dengan melapor kemudian adalah bentuk pengambilan keputusan yang bertanggung jawab dalam situasi mendesak. Menunda tanpa solusi (B, D) merugikan masyarakat, mengambil keputusan tanpa transparansi (C) mengabaikan akuntabilitas, dan melempar tanggung jawab ke rekan (E) tidak mencerminkan kepemimpinan situasional yang baik." },
{ q:"Anda dihadapkan pada dua opsi penyelesaian masalah teknis: opsi pertama lebih cepat namun berisiko menimbulkan masalah baru di kemudian hari, opsi kedua lebih aman namun membutuhkan waktu lebih lama sementara tenggat sudah dekat. Bagaimana Anda memutuskan?", opts:["Mengevaluasi dampak dan risiko masing-masing opsi secara cermat, berkonsultasi singkat dengan pihak terkait bila memungkinkan, lalu memilih opsi yang paling seimbang antara kecepatan dan keamanan","Selalu memilih opsi tercepat tanpa mempertimbangkan risiko demi mengejar tenggat","Selalu memilih opsi teraman tanpa mempertimbangkan konsekuensi keterlambatan sama sekali","Menunda keputusan tanpa batas waktu sampai merasa benar-benar yakin seratus persen","Meminta orang lain yang memutuskan sepenuhnya agar tidak menanggung risiko keputusan sendiri"], a:0, sub:"Manajerial", pembahasan:"Pengambilan keputusan yang baik mempertimbangkan risiko dan manfaat secara seimbang serta melibatkan konsultasi singkat jika waktu memungkinkan. Memilih opsi tercepat tanpa evaluasi risiko (B) atau opsi teraman tanpa mempertimbangkan tenggat (C) terlalu ekstrem, menunda tanpa batas (D) memperburuk keadaan, dan melempar keputusan ke orang lain (E) menghindari tanggung jawab." },
{ q:"Anda menghadapi dilema antara mengikuti prosedur baku secara ketat atau memberikan pengecualian demi membantu warga dalam kondisi darurat yang sebenarnya wajar untuk dibantu, namun berisiko dipertanyakan oleh pengawas. Sikap terbaik adalah?", opts:["Memberikan bantuan sesuai batas kewenangan yang memungkinkan, mendokumentasikan alasan dan kondisi darurat tersebut secara jelas, serta melaporkannya secara transparan","Menolak membantu sepenuhnya dengan alasan prosedur harus diikuti tanpa pengecualian apa pun","Memberikan pengecualian penuh di luar wewenang tanpa dokumentasi maupun laporan kepada siapa pun","Membantu diam-diam tanpa dokumentasi agar tidak dipertanyakan pengawas di kemudian hari","Meminta warga tersebut mencari cara lain di luar jalur resmi tanpa bantuan apa pun dari Anda"], a:0, sub:"Manajerial", pembahasan:"Membantu sesuai wewenang dengan dokumentasi dan transparansi yang jelas menyeimbangkan kepatuhan prosedur dan empati kemanusiaan sekaligus menjaga akuntabilitas. Menolak total (B) mengabaikan nilai kemanusiaan pelayanan publik, melampaui wewenang tanpa dokumentasi (C, D) berisiko pelanggaran, dan melepas tanggung jawab (E) tidak mencerminkan pelayanan yang baik." },
{ q:"Rekan kerja satu ruangan dengan Anda beragama berbeda dan memiliki waktu ibadah yang kadang berbenturan dengan jadwal rapat internal tim. Sebagai anggota tim, sikap Anda sebaiknya?", opts:["Mengusulkan penjadwalan rapat yang mempertimbangkan waktu ibadah semua anggota agar semua bisa berpartisipasi penuh tanpa merasa dikorbankan keyakinannya","Membiarkan saja karena jadwal rapat sudah ditetapkan dan menganggap itu bukan masalah besar","Meminta rekan tersebut menyesuaikan diri sepenuhnya dengan jadwal rapat tanpa mempertimbangkan kebutuhan ibadahnya","Mengusulkan agar rekan tersebut tidak perlu hadir rapat sama sekali demi menghindari benturan jadwal","Membicarakan hal ini secara terbuka di depan tim dengan nada menyindir kebutuhan ibadah rekan tersebut"], a:0, sub:"SosioKultural", pembahasan:"Mengakomodasi kebutuhan ibadah semua anggota melalui penjadwalan yang inklusif menunjukkan kepekaan terhadap keberagaman yang sesungguhnya. Membiarkan (B) atau memaksa penyesuaian sepihak (C) mengabaikan kebutuhan rekan, mengeluarkan dari rapat (D) justru mengucilkan, dan menyindir secara terbuka (E) merupakan sikap tidak toleran yang jelas keliru." },
{ q:"Dalam satu tim kerja, anggota yang berasal dari daerah berbeda memiliki gaya komunikasi yang berbeda pula, sehingga beberapa kali menimbulkan kesalahpahaman karena perbedaan cara menyampaikan pendapat yang dianggap terlalu blak-blakan atau terlalu halus. Apa yang sebaiknya Anda lakukan?", opts:["Membuka dialog untuk saling memahami gaya komunikasi masing-masing dan menyepakati cara berkomunikasi yang nyaman bagi semua anggota tim","Menganggap gaya komunikasi rekan dari daerah tertentu sebagai kekurangan yang harus diubah sepenuhnya","Menghindari berinteraksi dengan rekan yang gaya komunikasinya berbeda agar tidak terjadi kesalahpahaman","Membicarakan perbedaan gaya komunikasi tersebut sebagai bahan candaan di depan tim","Membiarkan kesalahpahaman terus terjadi karena dianggap sebagai bagian alami dari perbedaan latar belakang"], a:0, sub:"SosioKultural", pembahasan:"Dialog terbuka untuk saling memahami dan menyepakati cara komunikasi bersama adalah bentuk kepekaan keberagaman yang paling konstruktif dalam tim. Menganggap gaya komunikasi tertentu sebagai kekurangan (B) tidak menghargai perbedaan, menghindari interaksi (C) memperburuk kekompakan, menjadikan bahan candaan (D) berpotensi menyakiti, dan membiarkan (E) tidak menyelesaikan masalah komunikasi tim." },
{ q:"Anda ditempatkan bertugas di daerah dengan budaya, bahasa, dan kebiasaan masyarakat yang sangat berbeda dari daerah asal Anda, sehingga di awal Anda merasa canggung berinteraksi dengan masyarakat setempat. Sikap yang paling tepat adalah?", opts:["Meluangkan waktu mempelajari budaya dan kebiasaan setempat, bersikap terbuka, dan menghormati adat istiadat yang berlaku demi membangun hubungan baik dengan masyarakat","Tetap mempertahankan kebiasaan asal Anda sepenuhnya dan berharap masyarakat setempat yang menyesuaikan","Membatasi interaksi dengan masyarakat setempat seminimal mungkin untuk menghindari kecanggungan","Menilai kebiasaan masyarakat setempat sebagai sesuatu yang aneh dan kurang tepat dibandingkan daerah asal","Meminta segera dipindahkan ke daerah lain yang lebih sesuai dengan latar belakang budaya Anda"], a:0, sub:"SosioKultural", pembahasan:"Mempelajari dan menghormati budaya setempat sambil tetap terbuka adalah sikap paling adaptif dan menunjukkan kepekaan keberagaman yang tinggi bagi seorang ASN. Mempertahankan kebiasaan asal secara kaku (B) atau menilai budaya setempat negatif (D) tidak menghargai perbedaan, membatasi interaksi (C) menghambat pelayanan, dan meminta pindah (E) menghindari tantangan alih-alih beradaptasi." },
{ q:"Anda mendengar seorang rekan kerja melontarkan komentar bernada merendahkan suku atau etnis tertentu saat mengobrol santai di kantor, tanpa menyadari ada rekan lain yang berasal dari etnis tersebut mendengarnya. Apa yang Anda lakukan?", opts:["Menegur secara halus dan pribadi bahwa komentar tersebut tidak pantas dan bisa menyakiti perasaan rekan lain, sambil mengingatkan pentingnya menghargai keberagaman","Mengabaikan komentar tersebut karena dianggap hanya candaan biasa yang tidak perlu dipermasalahkan","Ikut tertawa mendukung komentar tersebut agar tidak dianggap terlalu serius oleh rekan kerja","Langsung melaporkan rekan tersebut kepada atasan untuk diberi sanksi tanpa menegurnya terlebih dahulu","Menceritakan kejadian tersebut kepada rekan lain sebagai bahan gosip tanpa menindaklanjuti apa pun"], a:0, sub:"SosioKultural", pembahasan:"Menegur secara halus dan personal adalah cara paling efektif mengoreksi sikap yang kurang menghargai keberagaman tanpa mempermalukan rekan di depan umum. Mengabaikan (B) atau ikut tertawa (C) memperkuat sikap tidak toleran tersebut, melapor langsung tanpa teguran dulu (D) terlalu cepat eskalasi, dan menyebarkan sebagai gosip (E) tidak menyelesaikan masalah sama sekali." },
{ q:"Anda bertugas melayani warga penyandang disabilitas yang mengalami kesulitan mengakses loket layanan karena fasilitas yang ada belum sepenuhnya ramah difabel. Sikap paling tepat yang Anda lakukan adalah?", opts:["Membantu warga tersebut secara langsung agar tetap terlayani dengan baik saat itu, sekaligus mengusulkan perbaikan fasilitas yang lebih ramah difabel kepada pihak berwenang","Meminta warga tersebut kembali lagi setelah membawa pendamping karena keterbatasan fasilitas yang ada","Melayani seadanya tanpa berusaha membantu mengatasi kesulitan aksesibilitas yang dialami warga tersebut","Menyuruh warga tersebut mengurus melalui perwakilan keluarga saja tanpa upaya membantu langsung","Mengabaikan keterbatasan fasilitas karena dianggap bukan tanggung jawab Anda sebagai petugas loket"], a:0, sub:"SosioKultural", pembahasan:"Membantu langsung sekaligus mengusulkan perbaikan sistemik menunjukkan kepekaan terhadap keberagaman kondisi masyarakat, termasuk penyandang disabilitas, secara menyeluruh. Meminta kembali (B) atau mengalihkan ke keluarga (D) menyulitkan warga, melayani seadanya (C) dan mengabaikan (E) menunjukkan kurangnya empati serta tanggung jawab terhadap aksesibilitas layanan publik." },
{ q:"Anda baru saja pindah tugas ke lingkungan kerja baru dan merasa kesulitan membaur dengan rekan-rekan yang sudah lama saling mengenal serta memiliki kebiasaan kelompok tersendiri. Apa yang sebaiknya Anda lakukan?", opts:["Bersikap terbuka dan proaktif memperkenalkan diri, menunjukkan minat mengenal kebiasaan tim, serta ikut berkontribusi dalam kegiatan bersama secara bertahap","Menunggu rekan-rekan lain yang mendekati Anda terlebih dahulu tanpa berusaha memulai interaksi","Menjaga jarak sepenuhnya dan fokus hanya pada pekerjaan tanpa berusaha membangun relasi sosial","Memaksakan diri masuk ke kelompok tertentu meskipun kurang nyaman demi terlihat diterima","Mengkritik kebiasaan kelompok yang sudah terbentuk karena dianggap eksklusif dan tidak ramah"], a:0, sub:"SosioKultural", pembahasan:"Bersikap proaktif dan terbuka untuk membaur secara bertahap adalah cara terbaik membangun hubungan sosial di lingkungan baru tanpa memaksakan diri. Menunggu didekati (B) atau menjaga jarak total (C) memperlambat proses adaptasi, memaksakan diri masuk kelompok (D) bisa terasa tidak tulus, dan mengkritik kebiasaan yang ada (E) berisiko menimbulkan kesan negatif di awal." },
{ q:"Anda ditugaskan membangun relasi kerja dengan tokoh masyarakat setempat yang memiliki pengaruh besar namun dikenal cukup tertutup terhadap pendatang baru dari instansi pemerintah. Pendekatan apa yang paling tepat?", opts:["Mendekati secara bertahap dengan menunjukkan itikad baik, mendengarkan aspirasi mereka terlebih dahulu, dan membangun kepercayaan sebelum menyampaikan kepentingan tugas Anda","Langsung menyampaikan kepentingan tugas Anda tanpa berusaha membangun kepercayaan terlebih dahulu","Menghindari berinteraksi dengan tokoh tersebut dan memilih jalur lain yang lebih mudah meski kurang efektif","Menekan tokoh tersebut menggunakan kewenangan instansi agar mau bekerja sama","Mengabaikan pentingnya relasi dengan tokoh tersebut karena dianggap akan memakan waktu terlalu lama"], a:0, sub:"SosioKultural", pembahasan:"Membangun kepercayaan secara bertahap dengan mendengarkan aspirasi terlebih dahulu adalah pendekatan sosial yang paling efektif menghadapi tokoh masyarakat yang tertutup. Menyampaikan kepentingan langsung (B) atau menekan dengan kewenangan (D) berisiko menimbulkan resistensi, menghindari (C) dan mengabaikan relasi (E) tidak menyelesaikan kebutuhan kerja sama yang sesungguhnya penting." },
{ q:"Anda memiliki konflik pribadi dengan seorang rekan kerja akibat kesalahpahaman di luar konteks pekerjaan, namun keduanya tetap harus berinteraksi secara profesional dalam tugas sehari-hari. Bagaimana Anda bersikap?", opts:["Tetap bersikap profesional dan sopan dalam konteks pekerjaan, serta mencari waktu yang tepat untuk menyelesaikan kesalahpahaman pribadi secara terpisah","Membawa konflik pribadi tersebut ke dalam interaksi pekerjaan sehingga memengaruhi kualitas kerja sama","Menghindari sepenuhnya interaksi dengan rekan tersebut meskipun pekerjaan menuntut koordinasi","Menceritakan konflik pribadi tersebut kepada rekan-rekan lain agar mereka memihak Anda","Bersikap dingin dan pasif-agresif kepada rekan tersebut selama bekerja tanpa menyelesaikan akar masalah"], a:0, sub:"SosioKultural", pembahasan:"Memisahkan urusan profesional dan pribadi sambil tetap berupaya menyelesaikan konflik secara terpisah menunjukkan kematangan dalam berhubungan sosial. Membawa konflik ke pekerjaan (B) atau bersikap pasif-agresif (E) merusak profesionalisme, menghindari interaksi (C) menghambat tugas, dan mencari dukungan pihak lain (D) berpotensi memperluas konflik secara tidak sehat." },
{ q:"Anda diundang oleh warga setempat untuk menghadiri acara sosial kemasyarakatan di luar jam kerja, seperti hajatan atau syukuran, yang sebenarnya bisa memperkuat hubungan Anda dengan masyarakat yang dilayani. Namun Anda merasa lelah dan ingin beristirahat. Sikap terbaik adalah?", opts:["Mengusahakan hadir meski sebentar untuk menghormati undangan dan mempererat hubungan sosial dengan masyarakat, selama masih memungkinkan bagi Anda","Menolak seluruh undangan dengan alasan lelah tanpa mempertimbangkan pentingnya hubungan sosial tersebut","Menghadiri acara tersebut tetapi bersikap acuh dan segera pulang tanpa berinteraksi dengan warga","Meminta rekan kerja lain menghadiri acara tersebut menggantikan Anda tanpa penjelasan kepada warga","Selalu memaksakan diri hadir di setiap acara sosial tanpa mempertimbangkan kondisi kesehatan atau kebutuhan istirahat pribadi"], a:0, sub:"SosioKultural", pembahasan:"Mengusahakan hadir meski sebentar menyeimbangkan kebutuhan pribadi dengan pentingnya membangun hubungan sosial dengan masyarakat yang dilayani. Menolak total (B) mengabaikan kesempatan mempererat relasi, hadir namun acuh (C) kurang bermakna, mendelegasikan tanpa penjelasan (D) kurang sopan, dan memaksakan diri di setiap acara (E) tidak realistis serta mengabaikan kebutuhan pribadi yang wajar." },
{ q:"Seorang rekan kerja terlihat murung dan kinerjanya menurun beberapa hari terakhir karena sedang menghadapi masalah keluarga yang berat, namun ia belum menceritakannya kepada siapa pun di kantor. Sikap Anda sebagai rekan kerja adalah?", opts:["Mendekatinya dengan cara yang tidak menghakimi, menunjukkan kepedulian, dan memberi ruang jika ia ingin bercerita, tanpa memaksa jika ia belum siap","Menegurnya secara terbuka di depan tim karena kinerjanya menurun tanpa mempertimbangkan kemungkinan penyebabnya","Mengabaikan perubahan sikapnya karena dianggap urusan pribadi yang tidak perlu dicampuri sama sekali","Menyebarkan dugaan mengenai masalahnya kepada rekan-rekan lain agar mereka memaklumi kinerjanya","Melaporkan penurunan kinerjanya kepada atasan tanpa mencoba memahami situasinya terlebih dahulu"], a:0, sub:"SosioKultural", pembahasan:"Menunjukkan kepedulian tanpa menghakimi dan memberi ruang bercerita adalah bentuk empati yang tepat tanpa melanggar batas privasi rekan kerja. Menegur di depan umum (B) atau melapor tanpa memahami (E) mengabaikan kondisi personalnya, membiarkan sepenuhnya (C) terkesan tidak peduli, dan menyebarkan dugaan (D) melanggar privasi serta berpotensi menimbulkan gosip yang merugikan." },
{ q:"Seorang warga datang ke kantor Anda dalam keadaan emosional dan menangis karena mengadukan musibah yang baru saja menimpa keluarganya, sembari meminta bantuan administrasi yang cukup rumit. Bagaimana Anda meresponsnya?", opts:["Mendengarkan dengan sabar, menunjukkan empati atas musibah yang dialaminya, kemudian membantu proses administrasinya dengan penuh perhatian","Meminta warga tersebut menenangkan diri dulu di luar ruangan sebelum dilayani tanpa menunjukkan empati apa pun","Melayani secara administratif seperti biasa tanpa menanggapi kondisi emosionalnya sama sekali","Menyuruh warga tersebut datang kembali di lain waktu ketika sudah tidak emosional","Memberi tahu warga tersebut bahwa musibahnya bukan urusan kantor dan hanya administrasi yang bisa dibantu"], a:0, sub:"SosioKultural", pembahasan:"Mendengarkan dengan empati sebelum membantu proses administrasi menunjukkan kepekaan terhadap kondisi emosional masyarakat yang dilayani sekaligus tetap profesional menyelesaikan tugas. Meminta menenangkan diri sendiri (B) atau menyuruh kembali lain waktu (D) terkesan tidak peduli, melayani tanpa empati (C) kurang manusiawi, dan menyatakan bukan urusan kantor (E) sangat tidak pantas dalam pelayanan publik." },
{ q:"Salah satu bawahan Anda gagal menyelesaikan tugas penting karena kendala teknis di luar kendalinya, seperti gangguan sistem yang tidak bisa diprediksi, meskipun ia sudah berusaha maksimal. Bagaimana Anda menyikapinya?", opts:["Memahami situasinya, mengapresiasi usaha yang sudah dilakukan, dan bersama-sama mencari solusi agar tugas tetap dapat diselesaikan dengan cara lain","Tetap menyalahkannya sepenuhnya karena target tidak tercapai tanpa mempertimbangkan kendala yang dihadapi","Mengabaikan kegagalan tersebut tanpa mendiskusikan solusi maupun evaluasi apa pun","Melaporkan kegagalannya kepada pimpinan yang lebih tinggi tanpa memberi kesempatan penjelasan terlebih dahulu","Mengambil alih seluruh tugasnya sebagai hukuman atas kegagalan yang terjadi"], a:0, sub:"SosioKultural", pembahasan:"Memahami kendala di luar kendali bawahan sambil tetap solutif mencari jalan keluar adalah bentuk empati kepemimpinan yang membangun kepercayaan tim. Menyalahkan sepenuhnya (B) tidak adil karena penyebabnya di luar kendali, mengabaikan tanpa evaluasi (C) menghilangkan pembelajaran, melapor tanpa penjelasan (D) terlalu cepat menghakimi, dan mengambil alih sebagai hukuman (E) tidak membangun." },
{ q:"Anda melihat seorang rekan kerja kesulitan menyelesaikan tugasnya, namun ia terlihat gengsi dan enggan meminta bantuan karena takut dianggap tidak kompeten oleh rekan-rekan lain. Apa yang sebaiknya Anda lakukan?", opts:["Mendekatinya secara halus dan menawarkan bantuan tanpa membuatnya merasa direndahkan, misalnya dengan mengajak berdiskusi seolah membahas pekerjaan bersama","Membiarkannya berjuang sendiri karena ia tidak meminta bantuan secara langsung kepada Anda","Menawarkan bantuan secara terbuka di depan rekan-rekan lain tanpa mempertimbangkan perasaannya","Melaporkan kesulitannya kepada atasan tanpa terlebih dahulu menawarkan bantuan langsung kepadanya","Menyindirnya secara halus agar ia sadar dan mau meminta bantuan dengan sendirinya"], a:0, sub:"SosioKultural", pembahasan:"Menawarkan bantuan dengan cara yang halus dan tidak mempermalukan menunjukkan empati yang tinggi terhadap perasaan rekan kerja yang gengsi. Membiarkan (B) mengabaikan kesulitan yang sudah terlihat jelas, menawarkan di depan umum (C) berisiko mempermalukan, melapor tanpa mencoba membantu langsung (D) kurang inisiatif, dan menyindir (E) tidak menghargai perasaannya." },
{ q:"Anda menyadari ada ketegangan yang mulai muncul antara dua kelompok warga di wilayah kerja Anda akibat kesalahpahaman kecil terkait pembagian bantuan sosial, meskipun belum ada konflik terbuka. Apa langkah paling tepat sebagai ASN yang bertugas di wilayah tersebut?", opts:["Segera melakukan komunikasi dengan tokoh dari kedua kelompok untuk mengklarifikasi kesalahpahaman dan mencegah eskalasi sebelum konflik membesar","Menunggu sampai konflik benar-benar terjadi baru bertindak karena belum ada insiden nyata","Mengabaikan gejala tersebut karena dianggap urusan internal masyarakat yang tidak perlu dicampuri","Memihak salah satu kelompok yang dianggap lebih benar tanpa mendengarkan pihak lain","Menyebarkan informasi mengenai ketegangan tersebut secara luas tanpa upaya klarifikasi kepada kedua kelompok"], a:0, sub:"SosioKultural", pembahasan:"Bertindak cepat mengklarifikasi kesalahpahaman sebelum konflik membesar menunjukkan kepekaan sosial yang tinggi dan sikap preventif yang tepat. Menunggu insiden nyata (B) atau mengabaikan (C) berisiko konflik meluas, memihak salah satu pihak (D) memperburuk keadaan, dan menyebarkan informasi tanpa klarifikasi (E) justru berpotensi memperkeruh situasi." },
{ q:"Anda menyadari ada sekelompok warga rentan, seperti keluarga miskin dan penyandang disabilitas, yang sebenarnya berhak atas program bantuan namun tidak pernah mengajukan diri karena tidak mengetahui informasi atau merasa tidak berani datang ke kantor. Apa yang Anda lakukan?", opts:["Proaktif menjangkau kelompok tersebut melalui pendataan langsung atau kerja sama dengan tokoh setempat agar mereka mendapatkan informasi dan akses bantuan yang menjadi haknya","Menunggu mereka datang sendiri mengajukan permohonan karena itu adalah prosedur standar yang berlaku","Menganggap ketidaktahuan mereka bukan tanggung jawab Anda untuk diselesaikan","Memberikan bantuan hanya kepada warga yang aktif dan berani mengajukan permohonan","Membiarkan kondisi tersebut karena dianggap akan menambah beban kerja jika harus menjangkau langsung"], a:0, sub:"SosioKultural", pembahasan:"Menjangkau secara proaktif kelompok rentan yang tidak vokal menunjukkan kepekaan sosial tinggi terhadap kesenjangan akses layanan yang sering luput dari perhatian. Menunggu mereka datang sendiri (B) mengabaikan realitas hambatan yang mereka hadapi, menganggap bukan tanggung jawab (C, E) tidak sesuai semangat pelayanan publik yang inklusif, dan hanya melayani yang aktif (D) memperlebar kesenjangan." },
{ q:"Anda menyadari suasana kerja tim yang biasanya akrab tiba-tiba menjadi tegang dan canggung tanpa ada penjelasan yang jelas dari siapa pun mengenai penyebabnya. Sebagai anggota tim, apa yang Anda lakukan?", opts:["Mengamati situasi dengan peka, lalu mencoba menanyakan secara personal kepada anggota tim yang tepercaya untuk memahami penyebab ketegangan tersebut sebelum berdampak lebih luas","Mengabaikan perubahan suasana tersebut karena dianggap akan hilang dengan sendirinya seiring waktu","Membicarakan ketegangan tersebut secara terbuka di rapat tim tanpa mengetahui penyebab pastinya terlebih dahulu","Ikut menjaga jarak dengan semua anggota tim mengikuti suasana yang tegang tersebut","Menyebarkan spekulasi mengenai penyebab ketegangan tersebut kepada rekan-rekan lain"], a:0, sub:"SosioKultural", pembahasan:"Mengamati dengan peka lalu mencari tahu penyebab secara personal sebelum mengambil tindakan menunjukkan kepekaan sosial yang matang dalam membaca dinamika tim. Mengabaikan (B) berisiko masalah membesar tanpa penyelesaian, membicarakan di forum terbuka tanpa informasi jelas (C) bisa memperburuk suasana, ikut menjaga jarak (D) memperparah keretakan, dan menyebarkan spekulasi (E) tidak bertanggung jawab." },
{ q:"Anda melihat sebuah isu SARA mulai berkembang dan dibahas dengan nada provokatif di grup percakapan kantor yang diikuti banyak pegawai. Sebagai anggota grup, apa yang paling tepat Anda lakukan?", opts:["Mengingatkan secara sopan bahwa pembahasan tersebut sensitif dan berpotensi memecah belah, serta mengajak agar diskusi kembali ke topik yang lebih konstruktif","Ikut berpartisipasi dalam diskusi tersebut untuk menyampaikan pendapat pribadi mengenai isu SARA itu","Membiarkan diskusi tersebut berlanjut karena dianggap hak setiap orang untuk berpendapat di grup","Keluar dari grup tersebut tanpa memberi peringatan apa pun kepada anggota lain","Membagikan isu tersebut ke grup lain agar lebih banyak orang mengetahui dan mendiskusikannya"], a:0, sub:"SosioKultural", pembahasan:"Mengingatkan secara sopan dan mengarahkan kembali ke topik konstruktif menunjukkan kepekaan sosial dalam mencegah isu sensitif berkembang menjadi konflik yang lebih luas. Ikut berpartisipasi (B) berisiko memperkeruh suasana, membiarkan (C) membiarkan potensi konflik berkembang, keluar tanpa peringatan (D) menghindar dari tanggung jawab, dan menyebarluaskan (E) justru memperbesar risiko perpecahan." },
{ q:"Wilayah kerja Anda sedang mengalami suasana tegang menjelang pemilihan kepala daerah karena dukungan masyarakat terbelah tajam antara dua kelompok pendukung calon yang berbeda. Sebagai ASN yang bertugas di sana, sikap terbaik Anda adalah?", opts:["Bersikap netral dalam pelayanan kepada seluruh kelompok masyarakat tanpa membedakan preferensi politik, serta aktif menjaga komunikasi yang menenangkan situasi","Menunjukkan dukungan terbuka kepada salah satu pasangan calon yang menurut Anda paling baik","Menghindari seluruh kegiatan pelayanan masyarakat sampai suasana politik mereda dengan sendirinya","Ikut menyebarkan pandangan pribadi mengenai calon tertentu kepada masyarakat yang dilayani","Bersikap acuh terhadap potensi ketegangan tersebut karena dianggap bukan urusan ASN untuk dijaga"], a:0, sub:"SosioKultural", pembahasan:"Netralitas dalam pelayanan disertai peran aktif menenangkan situasi adalah wujud peran ASN sebagai perekat bangsa di tengah polarisasi politik lokal. Mendukung terbuka (B) atau menyebarkan pandangan pribadi (D) melanggar prinsip netralitas ASN, menghindari pelayanan (C) merugikan masyarakat, dan bersikap acuh (E) mengabaikan tanggung jawab menjaga kerukunan sosial di wilayah tugas." },
{ q:"Kantor Anda merencanakan sebuah acara perayaan hari besar nasional yang melibatkan berbagai kelompok masyarakat dengan latar belakang agama dan etnis yang beragam di wilayah tersebut. Bagaimana sebaiknya Anda berkontribusi dalam perencanaan acara ini?", opts:["Mengusulkan rangkaian acara yang inklusif dan mengakomodasi keberagaman latar belakang peserta, sehingga semua kelompok merasa dihargai dan turut berpartisipasi","Mengusulkan acara yang hanya merepresentasikan kelompok mayoritas di wilayah tersebut demi kemudahan penyelenggaraan","Tidak ikut berkontribusi dalam perencanaan karena dianggap bukan tanggung jawab utama Anda","Mengusulkan agar acara tersebut dibatasi hanya untuk kalangan pegawai kantor tanpa melibatkan masyarakat umum","Menyerahkan seluruh perencanaan kepada pihak lain tanpa memberikan masukan apa pun mengenai keberagaman peserta"], a:0, sub:"SosioKultural", pembahasan:"Mengusulkan acara yang inklusif dan mengakomodasi keberagaman adalah kontribusi nyata ASN sebagai perekat bangsa dalam kegiatan yang melibatkan masyarakat luas. Merepresentasikan hanya kelompok mayoritas (B) mengabaikan keberagaman, tidak berkontribusi (C) menyia-nyiakan kesempatan berperan, membatasi peserta (D) mengurangi makna perekat bangsa, dan tidak memberi masukan (E) kurang proaktif." },
{ q:"Anda mendapati sebuah berita hoaks yang berpotensi memecah belah antarkelompok masyarakat sedang beredar cepat di wilayah kerja Anda melalui media sosial, dan beberapa warga mulai mempercayainya. Apa langkah paling tepat yang Anda ambil?", opts:["Melakukan klarifikasi informasi yang benar melalui saluran resmi dan mengajak tokoh masyarakat setempat untuk turut menyebarkan informasi yang akurat guna meredam keresahan","Membiarkan saja karena dianggap bukan wewenang Anda untuk meluruskan informasi di media sosial","Ikut menyebarkan berita tersebut kepada rekan kerja lain sekadar untuk berbagi informasi tanpa verifikasi","Menunggu instansi pusat yang mengklarifikasi tanpa melakukan tindakan apa pun di tingkat lokal","Mendebat warga yang mempercayai hoaks tersebut secara terbuka dengan nada menyalahkan"], a:0, sub:"SosioKultural", pembahasan:"Klarifikasi cepat melalui saluran resmi bersama tokoh masyarakat adalah langkah paling efektif meredam hoaks yang berpotensi memecah belah, sekaligus mencerminkan peran aktif sebagai perekat bangsa. Membiarkan (B) atau menunggu pusat (D) memperlambat penanganan, ikut menyebarkan tanpa verifikasi (C) memperburuk keadaan, dan mendebat dengan nada menyalahkan (E) berisiko menimbulkan resistensi dan konflik baru." },
{ q:"Di lingkungan tempat tinggal Anda yang majemuk, dua kelompok pemuda antardusun terlibat gesekan kecil akibat kesalahpahaman saat kegiatan olahraga bersama, dan Anda diminta warga untuk membantu meredakan situasi karena dikenal sebagai ASN yang dipercaya. Apa yang sebaiknya Anda lakukan?", opts:["Memfasilitasi pertemuan kedua kelompok pemuda secara netral, mendorong dialog untuk saling memahami, dan mengingatkan pentingnya menjaga kerukunan sebagai sesama warga bangsa","Menolak terlibat karena merasa itu urusan pemuda setempat yang bukan bagian dari tugas kedinasan Anda","Memihak kelompok yang lebih dekat dengan Anda secara pribadi agar cepat merasa didukung","Menyerahkan sepenuhnya penyelesaian kepada aparat keamanan tanpa mencoba menjembatani dialog terlebih dahulu","Membiarkan gesekan tersebut mereda dengan sendirinya tanpa upaya mediasi apa pun dari Anda"], a:0, sub:"SosioKultural", pembahasan:"Memfasilitasi dialog secara netral dan mengingatkan nilai kerukunan menunjukkan peran ASN sebagai perekat bangsa yang aktif menjaga kohesi sosial di tengah masyarakat majemuk. Menolak terlibat (B) menyia-nyiakan kepercayaan warga, memihak salah satu kelompok (C) memperburuk gesekan, melimpahkan seluruhnya ke aparat tanpa upaya dialog (D) kurang proaktif, dan membiarkan (E) berisiko gesekan kecil membesar menjadi konflik terbuka." }
);
